style.css:
/* MIDNIGHT BLUE SPARKLE — CHATGPT */

/* PALETA */
:root {
  --night: #071629;
  --navy: #102D50;
  --blue: #205B91;
  --cyan: #83CFFF;
  --ice: #D8F3FF;
}

/* FONDO GENERAL */
html, body {
  background: var(--night) !important;
  color: var(--ice) !important;
}

/* BARRA LATERAL */
nav,
aside {
  background: #091D35 !important;
}

/* ÁREA PRINCIPAL */
main {
  background: var(--night) !important;
}

/* MENSAJES */
[data-message-author-role="assistant"] {
  border-radius: 16px !important;
}

/* CAJA DE ESCRITURA */
form,
form textarea {
  border-radius: 18px !important;
}

/* BOTONES */
button {
  transition: all .3s ease !important;
}

button:hover {
  box-shadow: 0 0 12px #83CFFF88 !important;
}

/* ENLACES */
a {
  color: var(--cyan) !important;
}

a:hover {
  text-shadow: 0 0 8px var(--cyan);
}

/* TÍTULOS */
h1, h2, h3 {
  color: var(--ice) !important;
  text-shadow: 0 0 7px #83CFFF55;
}

/* SCROLLBAR */
::-webkit-scrollbar {
  width: 8px;
}

::-webkit-scrollbar-thumb {
  background: var(--blue);
  border-radius: 10px;
}

::-webkit-scrollbar-track {
  background: var(--night);
}

/* ANIMACIÓN */
@keyframes sparkleGlow {
  0%, 100% {
    filter: drop-shadow(0 0 2px #83CFFF44);
  }
  50% {
    filter: drop-shadow(0 0 6px #83CFFF99);
  }
}

button:hover,
a:hover {
  animation: sparkleGlow 1.5s infinite;
}

/* REDUCIR MOVIMIENTO */
@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after {
    animation: none !important;
    transition: none !important;
  }
}
